void ProcessAndSaveResources(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
  if (wait_state != WAITING) {
    return;
  }

  if (resources_list.size() != referrers_list.size()) {
    return;
  }

  int total_items = resources_list.size() + frames_list.size();
  if (download_progress_handler) {
    download_progress_handler->Update(total_items);
  }

  for (size_t i = 0; i < resources_list.size(); ++i) {
    SaveItem item;
    item.url = resources_list[i];
    item.referrer = referrers_list[i];
    waiting_queue.push_back(item);
  }

  for (const auto& frame_url : frames_list) {
    SaveItem item;
    item.url = frame_url;
    waiting_queue.push_back(item);
  }

  if (waiting_queue.empty()) {
    // Treat as user cancellation.
    OnSaveCancelled();
    return;
  }

  wait_state = SAVING;
  StartSavingProcess();
}

void process_savable_resources(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    if (!is_appropriate_wait_state()) {
        return;
    }

    if (resources_list.size() != referrers_list.size()) {
        return;
    }

    int total_items = resources_list.size() + frames_list.size();
    update_download_progress(total_items);

    for (size_t i = 0; i < resources_list.size(); ++i) {
        SaveItem item;
        item.url = resources_list[i];
        item.referrer = referrers_list[i];
        add_to_waiting_queue(item);
    }

    for (size_t i = 0; i < frames_list.size(); ++i) {
        SaveItem item;
        item.url = frames_list[i];
        item.referrer = Referrer(); // Assuming default referrer for frames
        add_to_waiting_queue(item);
    }

    if (waiting_queue_size() == 0) {
        handle_user_cancellation();
    }

    update_wait_state();
    start_saving_process();
}
